 const legalGuide=globalThis.RodavoltLegalGuide;
 let legalGuideGroup='all';
 function legalGuideView(){
  const list=legalGuideGroup==='all'?legalGuide.items:legalGuide.items.filter(i=>i.group===legalGuideGroup);
  const counts=[[LD.docs.length,'modelos e formulários','textos para preencher e revisar'],[legalGuide.items.length,'tipos da operação','organizados por momento'],[LD.entryIds.length,'modelos de entrada','pacote do motorista'],[2,'instrumentos externos','apólice e contrato de crédito']];
  return heading('MEU ADVOGADO · DOCUMENTOS DA OPERAÇÃO','Seus contratos, em um só lugar.','Prepare os textos, confira as condições e leve a versão preenchida ao advogado.',btn('Baixar roteiro para o advogado','legal-guide-download'))+
   legalDocumentsPanel()+
   `<div class="legal-guide-counts">${counts.map(([n,label,detail])=>`<div><strong>${n}</strong><span>${label}<br><small>${detail}</small></span></div>`).join('')}</div>
   <div class="legal-guide-boundary"><strong>Texto preparado não é aprovação jurídica nem assinatura.</strong><p>Configure as condições da empresa, do carro e da loja uma vez. Em cada uso, troque motorista, vínculo e fatos do evento. Contrato reduz riscos; seguro adequado, manutenção e provas também são necessários.</p></div>
   <details class="legal-business"><summary>Antes de contratar: formalização e condições da empresa</summary><p>Defina com contador e advogado a pessoa que assina, constituição/registro, CNPJ, poderes de representação, atividades, tributação, notas fiscais e exigências locais. Anexos podem integrar o contrato principal; recibos, ocorrências e acordos são usados quando o fato ocorrer. Esta é uma organização recomendada para o piloto, não uma lista universal de obrigações legais.</p></details>
   <div class="legal-guide-filters" role="group" aria-label="Filtrar documentos por etapa">${[['all','Todos · '+legalGuide.items.length],...legalGuide.groups.map(g=>[g.id,g.name])].map(([id,label])=>btn(label,'legal-guide-filter',legalGuideGroup===id?'primary':'',`data-group="${id}" aria-pressed="${legalGuideGroup===id}"`)).join('')}</div>
   <div class="legal-guide-list">${legalGuide.groups.filter(g=>list.some(i=>i.group===g.id)).map(g=>`<section aria-labelledby="legal-group-${g.id}"><div class="legal-guide-section"><h2 id="legal-group-${g.id}">${g.name}</h2><p>${g.description}</p></div><ol class="legal-guide-items" start="${list.find(i=>i.group===g.id).number}">${list.filter(i=>i.group===g.id).map(i=>`<li value="${i.number}"><span class="legal-guide-number" aria-hidden="true">${String(i.number).padStart(2,'0')}</span><div class="legal-guide-copy"><span class="eyebrow">${esc(i.kind)}</span><h3>${esc(i.title)}</h3><p>${esc(i.purpose)}</p><small><strong>Quando usar:</strong> ${esc(i.when)}</small></div><div class="legal-guide-actions">${tag(legalGuide.availability[i.availability],'amber')}${btn('Abrir '+i.documentIds.length+' modelo(s)','legal-document-guide','primary',`data-guide="${i.number}" aria-label="Abrir modelos: ${esc(i.title)}"`)}${btn('O que conferir','legal-guide-item','',`data-id="${i.id}" aria-label="O que conferir: ${esc(i.title)}"`)}</div></li>`).join('')}</ol></section>`).join('')}</div>
   <details class="legal-guide-notes"><summary>Cuidados que o contrato sozinho não resolve</summary><ul><li>A locadora pode responder por danos a terceiros. Cláusula de ressarcimento do motorista não impede a pretensão do terceiro. <a href="${legalGuide.sources.liability.url}" target="_blank" rel="noopener noreferrer">STF · Súmula 492</a>.</li><li>Conferir a apólice para locação a terceiros e uso em aplicativo; não presumir cobertura de seguro particular.</li><li>Não presumir culpa por avaria, reter caução sem prestação de contas ou exigir confissão de dívida em branco.</li><li>A rotina precisa corresponder ao contrato: uma declaração de autonomia não afasta, sozinha, eventual discussão trabalhista.</li><li>As vendas devem respeitar direitos do consumidor, regularidade dos produtos e emissão fiscal definida com o contador.</li></ul></details>
   <details class="legal-guide-notes"><summary>Assinou pelo GOV.BR? Como conferir o arquivo</summary><ol><li>Conclua o preenchimento e a revisão jurídica/comercial; gere a via final e confira os anexos.</li><li>As partes assinam externamente. O motorista devolve o PDF original pelo acesso individual.</li><li>A gestão confere documento, versão, partes e poderes de quem assina.</li><li>Confira autoria e integridade no <a href="${legalGuide.sources.validator.url}" target="_blank" rel="noopener noreferrer">VALIDAR do ITI</a>, por ação própria. O app não envia arquivos automaticamente.</li><li>Guarde o original e o resultado. Registre o parecer e conclua as conferências de ambas as partes.</li></ol><p>Validação técnica não aprova cláusulas nem libera o carro sozinha. Os requisitos de cobrança/execução dependem do instrumento e da assinatura adotados.</p></details>
   <details class="legal-guide-notes"><summary>Fontes oficiais e data da conferência</summary><p>Conferidas em ${date(legalGuide.checkedOn)}. Aplicação ao caso e exigências específicas de Maringá/PR dependem de revisão profissional.</p><ul>${Object.values(legalGuide.sources).map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a></li>`).join('')}</ul></details>
   <div class="section-title gap"><div><h2>Documentos e assinaturas dos vínculos</h2><p>A preparação acima gera arquivos para revisão. A fila abaixo preserva os registros do fluxo operacional, sem assiná-los ou alterá-los automaticamente.</p></div></div>`;
 }
 function legalGuideItem(id){
  const i=legalGuide.items.find(i=>i.id===id);if(!i)throw new RangeError('Documento não encontrado no roteiro.');
  return `<div class="legal-guide-detail">${tag(legalGuide.availability[i.availability],'amber')}<p><strong>${esc(i.kind)}</strong> · ${esc(i.when)}</p><p>${esc(i.purpose)}</p><h3>O que precisa estar definido</h3><ul>${i.points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><h3>Quais provas guardar</h3><ul>${i.evidence.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><div class="notice amber gap">${esc(i.caution)}</div><h3>Textos disponíveis</h3><div class="actions">${i.documentIds.map(id=>btn(LD.get(id).title,'legal-document-edit','',`data-id="${id}"`)).join('')}</div><details class="gap"><summary>Referências para a revisão</summary><ul>${i.sources.map(k=>`<li><a href="${legalGuide.sources[k].url}" target="_blank" rel="noopener noreferrer">${esc(legalGuide.sources[k].name)}</a></li>`).join('')}</ul></details></div>`;
 }
 function legalGuideAction(action,e){if(action==='legal-guide-filter'){legalGuideGroup=legalGuide.groups.some(g=>g.id===e.dataset.group)?e.dataset.group:'all';render();return true;}if(action==='legal-guide-item'){const i=legalGuide.items.find(i=>i.id===e.dataset.id);if(!i)throw new RangeError('Documento não encontrado.');open(i.number+'. '+i.title,legalGuideItem(i.id));return true;}if(action==='legal-guide-download'){download('RODAVOLT-roteiro-documentos-para-advogado.txt',legalGuide.text());return true;}return false;}
